replays.action('bug', async (ctx) => {
  const t = ctx.getTime();
  const step = ctx.replay.steps.filter((s) => s.at <= t).at(-1);
  const near = ctx.replay.console.filter((c) => c.level === 'error' && Math.abs(c.at - t) < 2000);
  const body = [
    'Bug at ' + (t / 1000).toFixed(1) + ' s',
    'Step: ' + (step ? step.label : '(before the first step)'),
    'Console: ' + (near.map((c) => c.message).join(' | ') || 'no errors nearby'),
    'Expected: ',
    'Actual: ',
  ].join('\n');
  await ctx.comments.add({ at: t, body });
});
